package io.github.astelev.around_planet.gametest;
import io.github.astelev.around_planet.fuel.*;
import io.github.astelev.around_planet.propulsion.*;
import io.github.astelev.around_planet.compat.PropulsionPhysics;
import dev.ryanhcode.sable.api.SubLevelAssemblyHelper;
import dev.ryanhcode.sable.api.sublevel.SubLevelContainer;
import dev.ryanhcode.sable.sublevel.storage.SubLevelRemovalReason;
import dev.ryanhcode.sable.companion.math.BoundingBox3i;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.neoforge.fluids.*;
import net.neoforged.neoforge.fluids.capability.IFluidHandler.FluidAction;
import java.util.*;
import org.joml.Vector3d;
@net.neoforged.neoforge.gametest.PrefixGameTestTemplate(false)
public final class RocketFuelGameTests {
 @GameTest(template="empty",templateNamespace="around_planet",batch="pondusRocketScale",timeoutTicks=120)
 public static void pondusCoefficientChangesVolumeButPreservesImpulse(GameTestHelper h){if(!FuelMassBridge.pondus()){h.succeed();return;}var level=h.getLevel();var p=h.absolutePos(new BlockPos(1,2,1));level.setBlockAndUpdate(p,PropulsionRegistry.LIQUID.get().defaultBlockState());Object config=null;java.lang.reflect.Field field=null;double old=1;try{var be=(PropulsionBlockEntity)level.getBlockEntity(p);var cls=Class.forName("org.fractalinteractive.ci.pondus_inventory_fi.config.GlobalConfig");config=cls.getMethod("getInstance").invoke(null);field=cls.getField("fluidMassModifier");old=field.getDouble(config);field.setDouble(config,1);double full=FuelMassBridge.kgPerMb(be,false);field.setDouble(config,.01);double scaled=FuelMassBridge.kgPerMb(be,false);h.assertTrue(Math.abs(scaled-full*.01)<1e-12,"Global fluid modifier was ignored");be.rocket.fill(new FluidStack(CryogenicFluids.HYDROGEN.get(),1000),FluidAction.EXECUTE);be.rocket.fill(new FluidStack(CryogenicFluids.OXYGEN.get(),1000),FluidAction.EXECUTE);var burn=be.rocket.burn(.1,scaled,FuelMassBridge.kgPerMb(be,true));h.assertTrue(Math.abs(burn.mass()-.1)<1e-10&&Math.abs(burn.impulse()-.1*Bipropellant.HYDROLOX.exhaustSpeed())<1e-7,"Scaled propellant produced wrong momentum");h.succeed();}catch(ReflectiveOperationException e){throw new AssertionError(e);}finally{if(field!=null)try{field.setDouble(config,old);}catch(IllegalAccessException e){throw new AssertionError(e);}level.removeBlock(p,false);}}
 @GameTest(template="empty",templateNamespace="around_planet",batch="liquidRocket",timeoutTicks=120)
 public static void nativeMassLossEqualsExhaustMassAndImpulse(GameTestHelper h){h.runAfterDelay(3,()->{var level=h.getLevel();var c=SubLevelContainer.getContainer(level);var p=h.absolutePos(new BlockPos(1,2,1));level.setBlockAndUpdate(p,PropulsionRegistry.LIQUID.get().defaultBlockState());level.setBlockAndUpdate(p.below(),Blocks.REDSTONE_BLOCK.defaultBlockState());var source=(PropulsionBlockEntity)level.getBlockEntity(p);source.rocket.fill(new FluidStack(CryogenicFluids.HYDROGEN.get(),1000),FluidAction.EXECUTE);source.rocket.fill(new FluidStack(CryogenicFluids.OXYGEN.get(),1000),FluidAction.EXECUTE);var ship=SubLevelAssemblyHelper.assembleBlocks(level,p,List.of(p,p.below()),new BoundingBox3i(p.getX(),p.getY()-1,p.getZ(),p.getX(),p.getY(),p.getZ()));try{var be=ship.getPlot().getLoadedChunks().stream().flatMap(ch->ch.getChunk().getBlockEntities().values().stream()).filter(PropulsionBlockEntity.class::isInstance).map(PropulsionBlockEntity.class::cast).findFirst().orElseThrow();be.onLoad();be.configure(50);PropulsionBlockEntity.tick(level,be.getBlockPos(),be.getBlockState(),be);double before=ship.getSelfMassTracker().getMass();double f=be.rocket.fuel(),o=be.rocket.oxidizer(),kg=FuelMassBridge.kgPerMb(be,false),okg=FuelMassBridge.kgPerMb(be,true);h.assertTrue(before>=f*kg+o*okg,"Fuel was not included in native assembled mass");double declared=dev.ryanhcode.sable.physics.config.block_properties.PhysicsBlockPropertyHelper.getMass(level,be.getBlockPos(),be.getBlockState())+dev.ryanhcode.sable.physics.config.block_properties.PhysicsBlockPropertyHelper.getMass(level,be.getBlockPos().below(),level.getBlockState(be.getBlockPos().below()));h.assertTrue(Math.abs(before-declared)<1e-6,"Fuel mass was counted more than once: native="+before+" declared="+declared);var pipe=c.physicsSystem().getPipeline();pipe.resetVelocity(ship);PropulsionPhysics.step(c.physicsSystem(),.05);double used=(f-be.rocket.fuel())*kg+(o-be.rocket.oxidizer())*okg;h.assertTrue(Math.abs(used-2.5)<1e-8,"Wrong mass flow");h.assertTrue(Math.abs((before-ship.getSelfMassTracker().getMass())-used)<1e-6,"Native mass differs from exhausted mass: before="+before+" after="+ship.getSelfMassTracker().getMass()+" used="+used);h.assertTrue(Math.abs(be.actualThrust()-50*Bipropellant.HYDROLOX.exhaustSpeed())<1e-6,"Thrust does not follow effective mass flow");h.assertTrue(pipe.getLinearVelocity(ship,new Vector3d()).y>0,"Liquid engine did not apply native impulse");
  var saved=be.saveWithoutMetadata(level.registryAccess());double savedFuel=be.rocket.fuel();be.rocket.restore(0,0);be.loadWithComponents(saved,level.registryAccess());h.assertTrue(be.rocket.fuel()==savedFuel,"Fractional fuel lost on save");be.rocket.drain(new FluidStack(CryogenicFluids.OXYGEN.get(),4000),FluidAction.EXECUTE);be.rocket.restore(be.rocket.fuel(),0);var velocity=pipe.getLinearVelocity(ship,new Vector3d());PropulsionPhysics.step(c.physicsSystem(),.05);h.assertTrue(be.actualThrust()==0&&pipe.getLinearVelocity(ship,new Vector3d()).distance(velocity)<1e-8,"Fuel alone created free thrust");h.succeed();
 }finally{c.removeSubLevel(ship,SubLevelRemovalReason.REMOVED);}});}
}
